package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.repository.jobs.*;
import java.time.*;
import java.sql.Timestamp;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.*;
import tools.jackson.databind.node.ObjectNode;

/** Real original partial permits and seals in owned databases, with fictional retained AI outcomes. */
class SourceValuePartialSealTest {
    SourceValuePartialArchiveTest p;JdbcSourceValuePartialReceipts store;JdbcSourceStageRoots roots;SourceValuePartialSealService service;
    GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
    void setup(boolean mixed,boolean applied)throws Exception{
        p=new SourceValuePartialArchiveTest(){@Override GenerationJdbcStoreTest database(){return SourceValuePartialSealTest.this.database();}};p.setup(mixed);
        for(int n=0;n<p.f.f.plan.chunks().size();n++){p.f.prepare(n);if(applied)p.f.outcomes.complete(n);else p.f.db.jdbc.update("UPDATE jobs SET state='failed',call_count=3,revision=revision+1 WHERE id=?",p.f.f.plan.chunks().get(n).rootId());}
        store=new JdbcSourceValuePartialReceipts(p.f.db.source);roots=new JdbcSourceStageRoots(p.f.db.source);service=provider(p.f.db.writes,p.f.authority.service);
    }
    SourceValuePartialSealService provider(SharedWriteExecutor writes,SourceDedupPartialDependencyPermitService permits){return new SourceValuePartialSealService(p.f.service,p.service,store,roots,writes,new DataSourceTransactionManager(p.f.db.source),p.f.f.f.clock,permits);}
    SourceValuePartialSealService.Committed read(){return p.f.original.read(()->service.readCommitted(p.f.ref));}
    int seals(){return p.f.db.count("target_type='source_value_partial_result'");}
    @Test void ZeroValueAndAllAppliedValueStillSealActualOriginalPartialDedup()throws Exception{
        setup(false,false);int calls=p.f.db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class);var zero=service.seal(p.f.ref);assertNotNull(zero);assertEquals(zero.receiptJson(),read().receiptJson());assertEquals(1,seals());assertTrue(zero.proof().fragments().isEmpty());assertEquals(1,CanonicalJson.parse(zero.proof().json()).get("accepted").asInt());assertEquals(1,CanonicalJson.parse(zero.proof().json()).get("missing").size());assertEquals(0,p.f.db.count("record_kind='logical_task' AND task_type='news_value'"));assertEquals(calls,p.f.db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));var empty=CanonicalJson.parse("{\"schema_version\":\"source-stage-native-capture-v1\",\"roots\":[]}");assertEquals(CanonicalJson.hash(CanonicalJson.Domain.ACTION,empty),CanonicalJson.parse(zero.receiptJson()).get("native_capture_hash").asText());
        setup(true,true);var captured=p.f.read();assertFalse(captured.hasFailures());assertEquals(SourceDedupPartialSealService.nativeHash(captured),SourceValuePartialSealService.nativeHash(captured));String state=p.f.db.jdbc.queryForObject("SELECT state FROM jobs WHERE id=?",String.class,p.f.ref.ownerId());var applied=service.seal(p.f.ref);assertNotNull(applied);assertEquals(200,CanonicalJson.parse(applied.proof().json()).get("applied_member_count").asInt());assertEquals(1,CanonicalJson.parse(applied.proof().json()).get("missing").size());assertEquals(state,p.f.db.jdbc.queryForObject("SELECT state FROM jobs WHERE id=?",String.class,p.f.ref.ownerId()));int count=p.f.db.count("1=1");assertEquals(applied.receiptJson(),service.seal(p.f.ref).receiptJson());assertEquals(count,p.f.db.count("1=1"));assertEquals(6,CanonicalJson.parse(applied.receiptJson()).size());assertFalse(applied.toString().contains("Fictional"));
    }
    @Test void MissingPermitOuterTransactionsAndStagedBytesCannotGrantASeal()throws Exception{
        setup(false,false);assertNotNull(p.service.stage(p.f.ref));var missing=new SourceValuePartialSealService(p.f.service,p.service,store,roots,p.f.db.writes,new DataSourceTransactionManager(p.f.db.source),p.f.f.f.clock);assertThrows(RuntimeException.class,()->missing.seal(p.f.ref));assertEquals(0,seals());assertThrows(RuntimeException.class,()->service.readCommitted(p.f.ref));assertThrows(RuntimeException.class,()->p.f.original.p1.tx(()->service.seal(p.f.ref)));assertThrows(RuntimeException.class,()->p.f.original.read(()->service.seal(p.f.ref)));assertThrows(RuntimeException.class,()->p.f.original.p1.tx(()->service.readCommitted(p.f.ref)));assertEquals(0,seals());assertNotNull(service.seal(p.f.ref));
    }
    @Test void CapturedValueNativeAndPartialDedupAuthorityAreRecheckedInsideTheWriter()throws Exception{
        setup(true,false);store=spy(store);doAnswer(call->{Object value=call.callRealMethod();p.f.db.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",p.f.f.plan.chunks().getFirst().rootId());return value;}).when(store).lockOwner(anyString());service=provider(p.f.db.writes,p.f.authority.service);assertThrows(RuntimeException.class,()->service.seal(p.f.ref));assertEquals(0,seals());
        store=new JdbcSourceValuePartialReceipts(p.f.db.source);var altered=spy(p.f.authority.service);doAnswer(call->{p.f.db.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",p.f.authority.f.plan.chunks().getLast().rootId());return call.callRealMethod();}).when(altered).verify(any(),any());service=provider(p.f.db.writes,altered);assertThrows(RuntimeException.class,()->service.seal(p.f.ref));assertEquals(0,seals());service=provider(p.f.db.writes,p.f.authority.service);assertNotNull(service.seal(p.f.ref));
    }
    @Test void OuterRollbackActualLostAckAndNativeCapacityNeverInventCompletion()throws Exception{
        setup(false,false);store=spy(store);doAnswer(call->{call.callRealMethod();throw new IllegalStateException("fictional value seal rollback");}).when(store).append(anyString(),anyString(),any());service=provider(p.f.db.writes,p.f.authority.service);assertThrows(RuntimeException.class,()->service.seal(p.f.ref));assertEquals(0,seals());setup(true,false);store=new JdbcSourceValuePartialReceipts(p.f.db.source);roots=spy(roots);doThrow(JdbcSourceStageRoots.CapacityRejected.class).when(roots).lockOriginal(anyList());service=provider(p.f.db.writes,p.f.authority.service);assertThrows(GenerationFlowService.CapacityGuarded.class,()->service.seal(p.f.ref));assertEquals(0,seals());roots=new JdbcSourceStageRoots(p.f.db.source);
        var fault=new DataSourceTransactionManager(p.f.db.source){boolean lost;@Override protected void doCommit(DefaultTransactionStatus status){super.doCommit(status);if(!lost&&!TransactionSynchronizationManager.isCurrentTransactionReadOnly()){lost=true;throw new org.springframework.transaction.TransactionSystemException("fictional value seal ACK lost");}}};var writes=new SharedWriteExecutor(new JdbcSharedWriteEntry(p.f.db.source),fault,()->25,n->{});service=provider(writes,p.f.authority.service);var committed=service.seal(p.f.ref);assertEquals(committed.receiptJson(),read().receiptJson());assertEquals(1,seals());service=provider(p.f.db.writes,p.f.authority.service);assertEquals(committed.receiptJson(),service.seal(p.f.ref).receiptJson());assertEquals(1,seals());
    }
    @Test void ReadonlyRestartRejectsUpdatedAtOnlyChangesAndRehashedUnknownReceiptFields()throws Exception{
        setup(true,false);var sealed=service.seal(p.f.ref);var nativeRoot=p.f.read().fragments().getFirst().nativeRoot();int count=p.f.db.count("1=1");p.f.db.jdbc.execute("DROP TABLE source_run_items");p.f.db.jdbc.execute("DROP TABLE analyzed_entities");service=provider(p.f.db.writes,p.f.authority.service);assertEquals(sealed.receiptJson(),read().receiptJson());assertEquals(count,p.f.db.count("1=1"));p.f.db.jdbc.update("UPDATE jobs SET updated_at=? WHERE id=?",Timestamp.from(nativeRoot.updatedAt().plusNanos(1000)),nativeRoot.id());assertThrows(RuntimeException.class,this::read);p.f.db.jdbc.update("UPDATE jobs SET updated_at=? WHERE id=?",Timestamp.from(nativeRoot.updatedAt()),nativeRoot.id());assertEquals(sealed.receiptJson(),read().receiptJson());var payload=(ObjectNode)CanonicalJson.parse(sealed.receiptJson());payload.put("extra",true);String changed=JdbcFrozenInputs.canonical(payload);p.f.db.jdbc.update("UPDATE jobs SET action_payload=?,action_payload_hash=? WHERE id=?",changed,JdbcGenerationLineage.hash(changed),JdbcSourceValuePartialReceipts.receiptId(p.f.ref.ownerId()));assertThrows(RuntimeException.class,this::read);assertEquals(1,seals());
    }
    @Test void OriginalLegacyValueFailureCanSealWithoutAPartialDedupPermit()throws Exception{
        var legacy=new SourceAnalysisParentStepTest(){@Override GenerationJdbcStoreTest database(){return SourceValuePartialSealTest.this.database();}};legacy.completedP1();legacy.step.step(legacy.candidate(legacy.handoffs.ref.ownerId()));var child=legacy.candidate(legacy.handoffs.read().p2Owner());legacy.step.step(child);var reference=legacy.reference(child.id());var plan=legacy.read(()->legacy.plans.readImmutable(reference));for(var chunk:plan.chunks())legacy.db.jdbc.update("UPDATE jobs SET state='failed',call_count=3,revision=revision+1 WHERE id=?",chunk.rootId());var results=new JdbcSourceDedupResults(legacy.db.source);var dependencies=new SourceDedupDependencyService(new JdbcSourceStageAvailability(legacy.db.source));var resolution=new SourceStageResolutionService(new JdbcSourceStageRoots(legacy.db.source),legacy.plans,legacy.p1.universes,legacy.parts,new JdbcFrozenInputs(legacy.db.source),results,new SourceDedupResultProofService(results,legacy.plans,legacy.p1.universes),new SourceValueResultProofService(results,legacy.plans,legacy.p1.universes,dependencies),dependencies);var tx=new DataSourceTransactionManager(legacy.db.source);var clock=Clock.fixed(plan.scope().cutoff().plusSeconds(1),ZoneOffset.UTC);var archive=new SourceValuePartialArchiveService(resolution,new JdbcSourceValuePartialBlocks(legacy.db.source),legacy.db.writes,tx,clock);var provider=new SourceValuePartialSealService(resolution,archive,new JdbcSourceValuePartialReceipts(legacy.db.source),new JdbcSourceStageRoots(legacy.db.source),legacy.db.writes,tx,clock);var committed=provider.seal(reference);assertNotNull(committed);assertEquals("source-value-stage-context-v1",CanonicalJson.parse(committed.proof().json()).get("stage_context").get("schema_version").asText());assertEquals(committed.receiptJson(),legacy.read(()->provider.readCommitted(reference)).receiptJson());
    }
}
